import{_ as e,o as r,c as t,a8 as a}from"./chunks/framework.BWjTbCIc.js";const u=JSON.parse('{"title":"汇基书院（东九龙） · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-c10c51a8","school_zh":"汇基书院（东九龙）","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"汇基书院（东九龙） · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-UCCKE-2021"],"rounds":["r1","unknown"]},"headers":[],"relativePath":"reports/school-c10c51a8/s1/2020-21-interview.md","filePath":"reports/school-c10c51a8/s1/2020-21-interview.md"}'),s={name:"reports/school-c10c51a8/s1/2020-21-interview.md"};function n(c,o,p,l,i,h){return r(),t("div",null,[...o[0]||(o[0]=[a('<h1 id="汇基书院-东九龙-·-2020-21年度-·-中一-·-面试" tabindex="-1">汇基书院（东九龙） · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#汇基书院-东九龙-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;汇基书院（东九龙） · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-c10c51a8">← 返回汇基书院（东九龙）资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-uccke-2021" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-uccke-2021" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-uccke-2021}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>介绍、阅读与个人追问</strong></p><p>部分先自我介绍，部分直接交谈；问题涉及是否参加过类似面试、当前感受、家庭活动、校园经历、宠物、闲暇、英文书及作者。根据介绍可要求说几句德语、说明三年服务生的职责、谁鼓励自己成为社工、最尊敬谁，或介绍乒乓球这项运动。</p><p><strong>文章与环球视野</strong></p><p>朗读屏幕上的短文并答理解题，有一组约两题；主题含城市中的马和社会贫困。另问什么是global vision、是否到过外国及难忘旅行。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语</p><p><strong>概括文章与个人生活</strong></p><p>听老师读文章后总结，或在英文朗读后改用中文概括内容并回答问题；另谈兴趣、平日活动及与家人做什么。</p><p><strong>全球暖化与绿色生活</strong></p><p>什么是全球暖化，为什么世界及香港开始关注，香港人忽略了什么？除常见三类回收物外还知道什么可回收，在学校建议什么环保项目，在家做过什么、如何响应绿色生活。</p><p><strong>手机、网购与快乐</strong></p><p>现代人手机成瘾的看法、使用习惯及Apps、怎样避免沉迷。网购对消费者和商家的好处，网店会否取代实体店。为何孩子从约9至10岁后到15岁快乐程度下降，怎样减压，分享近期快乐经历。</p></blockquote><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>家长交流：</strong> 语言未注明</p><p><strong>集体说明及问答</strong></p><p>有一位校长面对200多名家长的集体会面：家长分享选校原因、提问，校长回答并说明升中及录取后的入学手续。此环节不是每个家庭各自的个人面试。</p></blockquote>',12)])])}const _=e(s,[["render",n]]);export{u as __pageData,_ as default};
